import React, { useState, useEffect } from 'react';
import axios from 'axios';
import styled from 'styled-components'; // Add this line for styled-components

// Rest of your component code...

const FuelPage = () => {
  const [fuelData, setFuelData] = useState({
    fuel_date: '',
    bunk_name: '',
    total_amount: '',
    amount_paid: '',
  });

  const [lorryList, setLorryList] = useState([]);
  const [selectedLorryId, setSelectedLorryId] = useState(null); // Store selected lorry ID
  const [fuelDetails, setFuelDetails] = useState([]);

  // Fetch lorries on component mount
  useEffect(() => {
    const fetchLorries = async () => {
      try {
        const response = await axios.get('http://localhost:5001/api/lorries');
        setLorryList(response.data);
      } catch (error) {
        console.error('Error fetching lorries:', error);
      }
    };

    fetchLorries();
  }, []);

  // Handle form field changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFuelData({
      ...fuelData,
      [name]: value,
    });
  };

  // Handle lorry selection
  const handleLorrySelect = (e) => {
    setSelectedLorryId(e.target.value); // Set the selected lorry ID
  };

  // Add fuel data to the backend
  const addFuel = async () => {
    if (!selectedLorryId || !fuelData.fuel_date || !fuelData.bunk_name || !fuelData.total_amount || !fuelData.amount_paid) {
      alert('Please fill all fields correctly.');
      return;
    }

    try {
      const totalAmount = parseFloat(fuelData.total_amount);
      const amountPaid = parseFloat(fuelData.amount_paid);

      if (isNaN(totalAmount) || isNaN(amountPaid)) {
        alert('Total amount and Amount paid must be valid numbers.');
        return;
      }

      // Send POST request and store the response
      const response = await axios.post('http://localhost:5001/api/fuel/add', {
        lorry_id: selectedLorryId, // Pass the selected lorry_id
        fuel_date: fuelData.fuel_date,
        bunk_name: fuelData.bunk_name,
        total_amount: totalAmount,
        amount_paid: amountPaid,
      });

      console.log('Fuel added successfully:', response.data.message);

      // Update the fuel details list with new data
      setFuelDetails((prevState) => [...prevState, response.data]);

    } catch (error) {
      console.error('Error adding fuel', error);
      alert(`Error adding fuel: ${error.response ? error.response.data.error : 'Unknown error'}`);
    }
  };

  // Fetch fuel details for a specific lorry
  const fetchFuelDetails = async () => {
    if (!selectedLorryId) {
      alert('Please select a lorry.');
      return;
    }

    try {
      const response = await axios.get(`http://localhost:5001/api/fuel/${selectedLorryId}`);
      setFuelDetails(response.data);
    } catch (error) {
      console.error('Error fetching fuel details', error);
    }
  };

  // Delete fuel entry by ID
  const deleteFuel = async (fuelId) => {
    try {
      await axios.delete(`http://localhost:5001/api/fuel/${fuelId}`);
      alert('Fuel entry deleted successfully');
      setFuelDetails(fuelDetails.filter(fuel => fuel.id !== fuelId));
    } catch (error) {
      console.error('Error deleting fuel entry', error);
      alert('Error deleting fuel entry');
    }
  };

  return (
    <div>
      <h2>Fuel Entry</h2>

      {/* Display selected lorry_id */}
      <div style={{ textAlign: 'center', marginBottom: '20px' }}>
        <h3>{selectedLorryId ? `Lorry ID: ${selectedLorryId}` : 'Select Lorry'}</h3>
      </div>

      {/* Form to add fuel data */}
      <form>
        <div>
          <label htmlFor="lorry_id">Select Lorry:</label>
          <select id="lorry_id" onChange={handleLorrySelect} value={selectedLorryId || ''}>
            <option value="">-- Select Lorry --</option>
            {lorryList.map((lorry) => (
              <option key={lorry.id} value={lorry.id}>
                {lorry.registration_number} {/* Display lorry registration number */}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="fuel_date">Fuel Date:</label>
          <input
            type="date"
            id="fuel_date"
            name="fuel_date"
            value={fuelData.fuel_date}
            onChange={handleChange}
          />
        </div>

        <div>
          <label htmlFor="bunk_name">Bunk Name:</label>
          <input
            type="text"
            id="bunk_name"
            name="bunk_name"
            value={fuelData.bunk_name}
            onChange={handleChange}
          />
        </div>

        <div>
          <label htmlFor="total_amount">Total Amount:</label>
          <input
            type="number"
            id="total_amount"
            name="total_amount"
            value={fuelData.total_amount}
            onChange={handleChange}
          />
        </div>

        <div>
          <label htmlFor="amount_paid">Amount Paid:</label>
          <input
            type="number"
            id="amount_paid"
            name="amount_paid"
            value={fuelData.amount_paid}
            onChange={handleChange}
          />
        </div>

        <button type="button" onClick={addFuel}>
          Add Fuel
        </button>
      </form>

      {/* Fetch fuel details */}
      <button type="button" onClick={fetchFuelDetails}>
        Fetch Fuel Details
      </button>

      {/* Display the list of added fuel entries */}
      <div>
        <h3>Fuel Entries</h3>
        <ul>
          {fuelDetails.map((fuel) => (
            <li key={fuel.id}>
              Lorry ID: {fuel.lorry_id}, Fuel Date: {fuel.fuel_date}, Bunk Name: {fuel.bunk_name}, Total Amount: {fuel.total_amount}, Amount Paid: {fuel.amount_paid}
              <button onClick={() => deleteFuel(fuel.id)}>Delete</button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};



const Container = styled.div`
  padding: 20px;
  max-width: 1200px;
  margin: 0 auto;
`;

const LorryId = styled.h2`
  text-align: center;
  margin-bottom: 20px;
`;

const Section = styled.div`
  margin-bottom: 30px;
`;

const Form = styled.div`
  display: grid;
  gap: 10px;
  max-width: 400px;
  margin: 0 auto;

  input {
    padding: 10px;
    font-size: 14px;
    border: 1px solid #ddd;
    border-radius: 5px;
  }

  button {
    padding: 10px;
    font-size: 16px;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    &:hover {
      background-color: #0056b3;
    }
  }
`;

const DateContainer = styled.div`
  display: flex;
  gap: 20px;
  justify-content: center;
  margin-bottom: 20px;

  button {
    padding: 10px;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    &:hover {
      background-color: #0056b3;
    }
  }
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;

  th, td {
    padding: 12px;
    text-align: center;
    border: 1px solid #ddd;
  }

  th {
    background-color: #f4f4f4;
  }

  tr:nth-child(even) {
    background-color: #f9f9f9;
  }
`;

export default FuelPage;
